def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = [h[1] for h in history]
    my = [h[0] for h in history]
    opp_c = 0
    opp_d = 0
    for a in opp:
        if a == 'C':
            opp_c += 1
        else:
            opp_d += 1
    my_c = 0
    my_d = 0
    for a in my:
        if a == 'C':
            my_c += 1
        else:
            my_d += 1

    # Estimate opponent's "type" using behavior features rather than exact order.
    last = opp[-1]
    last2 = opp[-2] if n >= 2 else 'C'
    last3 = opp[-3] if n >= 3 else 'C'

    # Defection streaks at the end
    opp_d_streak = 0
    for a in reversed(opp):
        if a == 'D':
            opp_d_streak += 1
        else:
            break
    my_d_streak = 0
    for a in reversed(my):
        if a == 'D':
            my_d_streak += 1
        else:
            break

    # Recent windows
    w = 10
    rec = opp[-w:] if n >= w else opp
    rec_d = 0
    for a in rec:
        if a == 'D':
            rec_d += 1
    rec_n = len(rec)
    rec_rate = rec_d / float(rec_n)

    # Reward matrix analysis: how often has opponent taken advantage of our C?
    adv = 0  # opp D after my C
    mutual_c = 0
    mutual_d = 0
    punished_opp = 0  # opp C after my D
    for i in range(n):
        a = my[i]
        b = opp[i]
        if a == 'C' and b == 'D':
            adv += 1
        elif a == 'C' and b == 'C':
            mutual_c += 1
        elif a == 'D' and b == 'D':
            mutual_d += 1
        elif a == 'D' and b == 'C':
            punished_opp += 1

    # Endgame: known last rounds, defect aggressively but hedge slightly.
    remaining = 100 - n
    if remaining == 0:
        return 'D'
    if remaining <= 4:
        # If opponent is clearly cooperative, taking 5 is better; but they may also
        # defect. Against cooperative types, defect. Against defectors, defect too.
        return 'D'

    # If opponent has been essentially all cooperative (no D at all), exploit.
    if opp_d == 0:
        # Keep enough cooperation to not trigger a retaliation spiral from
        # forgiving retaliators; extract value with high probability.
        if n <= 2:
            return 'C'
        if remaining <= 8:
            return 'D'
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    # Early game: cooperate to signal, but only until we learn.
    if n <= 3:
        return 'C'

    # Strong, sustained opponent defection: defect to limit losses (avoid 0 payoff).
    if opp_d_streak >= 3:
        # If we've already been defecting and they continue, stay D.
        return 'D'

    # If opponent alternates or has moderate defection, use a forgiving
    # retaliatory rule but punish hard exploitation.

    # Exploitation signal: opponent defected right after we cooperated often.
    if adv >= 3 and adv * 2 >= n:
        # They're exploiting us; defect more.
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    # If opponent defected last round, retaliate (one-round echo) unless
    # they are mostly cooperative and defection is isolated.
    if last == 'D':
        # If mostly cooperative overall and this looks like a one-off, forgive.
        if opp_d <= max(1, n // 12) and n >= 15:
            if rng.random() < 0.5:
                return 'C'
        # If our last action was also D (we already retaliated), consider
        # de-escalating if their recent rate is low.
        if my_d_streak >= 2 and rec_rate < 0.3:
            if rng.random() < 0.4:
                return 'C'
        return 'D'

    # Opponent cooperated last round.
    # If we defected last round and they still cooperated, they are forgiving;
    # cooperate to keep the 3-3 stream, but occasionally exploit again.
    if last == 'C':
        if my_d_streak >= 1:
            # We've been extracting; if they keep cooperating, exploit more.
            if opp_d <= 2 and remaining > 10:
                if rng.random() < 0.6:
                    return 'D'
            return 'C'
        # Normal cooperation.
        # Rare defection probe against very cooperative opponents.
        if rec_rate <= 0.1 and remaining > 15:
            if rng.random() < 0.12:
                return 'D'
            return 'C'
        # If opponent shows moderate defection history, cooperate but watch.
        if rec_rate <= 0.35:
            return 'C'
        # Opponent has been fairly defective but just cooperated; test them
        # by cooperating (rewarding cooperation).
        return 'C'

    # Fallback
    return 'C'
